#!/usr/bin/env python3
"""Injects the admin 'Outreach' tab (DSQ-OUTREACH) into admin.html, after the DSQ-AUTOMAIL block.
   Targets come from data/institutions.json. Run: python3 tools/build_outreach_panel.py"""
import json, os, re
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
INS = json.load(open(os.path.join(ROOT, "data/institutions.json"), encoding="utf-8"))
ROUTE = {
 "University of Manchester": ("Students' Union advertising/media sales, plus student services. Union: Oxford Road, M13 9PR, 0161 275 2930. Verify who sells ad space.", ""),
 "Manchester Metropolitan University": ("The Union at Manchester Met, media sales. Reported: mediasales@mmu.ac.uk, 0161 247 1162. Verify on their site.", "https://www.theunionmmu.org/about-us/advertise-with-us"),
 "University of Salford": ("Salford Students' Union advertising, plus the University's careers/partnership team. Verify the contact on the Union's site.", ""),
 "University of Greater Manchester (formerly the University of Bolton)": ("Greater Manchester Students' Union and student services.", "https://greatermanchester.ac.uk/getting-in-touch"),
 "The Manchester College": ("Adult learners / student services.", "https://www.tmc.ac.uk/contact/"),
 "Salford City College": ("Adult learners / student services.", "https://www.salfordcc.ac.uk/market/adult/"),
 "Trafford & Stockport College Group": ("Student services / adult and professional skills.", "https://tscg.ac.uk/contact-us/"),
 "Tameside College": ("Adult part-time courses / student services.", "https://www.tameside.ac.uk/Pages/contactus"),
 "Hopwood Hall College": ("Adult learners / student services.", "https://www.hopwood.ac.uk/contact/"),
 "Bolton College": ("Student services / adult learners.", "https://www.boltoncollege.ac.uk/contact-us/"),
 "Wigan & Leigh College": ("Employer engagement / adults.", "https://www.wigan-leigh.ac.uk/employers/contact-us/"),
 "Oldham College and University Campus Oldham": ("Student services / adults.", "https://www.oldham.ac.uk/contact-us/"),
 "Bury College": ("Adults / University Centre.", "https://burycollege.ac.uk/adults")}
items = []
for k, kind in (("universities", "University"), ("colleges", "College")):
    for i in INS[k]:
        base = i["slug"].replace(".html", "")
        r = ROUTE[i["name"]]
        items.append({"id": base, "name": i["name"], "kind": kind, "page": "/" + i["slug"], "flyer": f"flyers/DriveSQ-student-offer-{base}.pdf", "tpl": "pre-out-" + base, "route": r[0], "routeUrl": r[1]})
JS = r'''<!-- DSQ-OUTREACH START (generated by tools/build_outreach_panel.py) -->
<script id="dsq-outreach">
/* Outreach tab: tracker for the 13 university & college outreach emails. Opens the right email template, links the flyer and student page,
   tracks status / date emailed / contact / notes (saved in growth_settings "outreach_tracker", with this-browser fallback),
   flags follow-ups after 7 days, and counts bookings from the student pages (the "Institution:" line in booking notes). */
(function () {
  "use strict";
  const ITEMS = __ITEMS__;
  const STATUS = [["none", "Not contacted"], ["emailed", "Emailed"], ["replied", "Replied"], ["talks", "In talks"], ["agreed", "Agreed"], ["declined", "Declined"], ["noreply", "No reply"]];
  const $ = (s, r) => (r || document).querySelector(s), $$ = (s, r) => Array.from((r || document).querySelectorAll(s));
  const h = v => String(v == null ? "" : v).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const db = () => window.sb || (typeof sb !== "undefined" ? sb : null);
  const toast = (m, t, ms) => { try { window.showToast(m, t || "", ms); } catch (e) { console.log(m); } };
  const KEY = "outreach_tracker", LS = "dsq_outreach_tracker";
  const S = { data: {}, counts: {}, loaded: false, saveT: 0, hasDb: true, filter: "all" };
  const today = () => new Date().toISOString().slice(0, 10);
  const days = d => d ? Math.floor((Date.now() - new Date(d + "T12:00:00")) / 864e5) : null;

  async function load() {
    try { S.data = JSON.parse(localStorage.getItem(LS) || "{}") || {}; } catch (e) { S.data = {}; }
    const c = db();
    if (c) {
      try { const r = await c.from("growth_settings").select("value").eq("key", KEY).maybeSingle(); if (r && r.data && r.data.value) S.data = Object.assign({}, S.data, r.data.value); else if (r && r.error) S.hasDb = false; } catch (e) { S.hasDb = false; }
      try {
        const r = await c.from("waiting_list").select("notes,created_at").ilike("notes", "%Institution:%").order("created_at", { ascending: false }).limit(3000);
        (r.data || []).forEach(x => {
          const m = String(x.notes || "").match(/(?:^|[\s|])Institution:\s*([^|\n]+)/i); if (!m) return;
          const nm = m[1].trim(), it = ITEMS.find(i => i.name === nm || nm.indexOf(i.name) === 0 || i.name.indexOf(nm) === 0); if (!it) return;
          const o = S.counts[it.id] = S.counts[it.id] || { n: 0, flyer: 0, last: "" };
          o.n++; if (/Source:\s*Campaign:\s*flyer/i.test(x.notes || "")) o.flyer++; if (!o.last) o.last = x.created_at;
        });
      } catch (e) {}
    }
    S.loaded = true;
  }
  function save() {
    try { localStorage.setItem(LS, JSON.stringify(S.data)); } catch (e) {}
    clearTimeout(S.saveT);
    S.saveT = setTimeout(async () => {
      const c = db(); if (!c) return;
      try { const r = await c.from("growth_settings").upsert({ key: KEY, value: S.data, updated_at: new Date().toISOString() }, { onConflict: "key" }); const el = $("#ocSaved"); if (el) el.textContent = r && r.error ? "Saved in this browser only" : "Saved ✓"; } catch (e) { const el = $("#ocSaved"); if (el) el.textContent = "Saved in this browser only"; }
    }, 600);
    const el = $("#ocSaved"); if (el) el.textContent = "Saving…";
  }
  const get = id => S.data[id] || (S.data[id] = { status: "none", emailed: "", contact: "", notes: "", flyer: false });

  function tile(l, v, s) { return `<div class="oc-tile"><div class="l">${l}</div><div class="n">${v}</div><div class="s">${s || ""}</div></div>`; }
  function render() {
    const p = $("#panel-outreach"); if (!p) return;
    const rows = ITEMS.map(i => ({ i, d: get(i.id), c: S.counts[i.id] || { n: 0, flyer: 0 } }));
    const cnt = k => rows.filter(r => r.d.status === k).length;
    const sent = rows.filter(r => r.d.status !== "none").length, bk = rows.reduce((a, r) => a + r.c.n, 0), fl = rows.reduce((a, r) => a + r.c.flyer, 0);
    const due = rows.filter(r => r.d.status === "emailed" && days(r.d.emailed) != null && days(r.d.emailed) >= 7).length;
    const shown = rows.filter(r => S.filter === "all" || (S.filter === "due" ? (r.d.status === "emailed" && days(r.d.emailed) != null && days(r.d.emailed) >= 7) : r.i.kind === S.filter || r.d.status === S.filter));
    p.innerHTML = `<style>#panel-outreach .oc-tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px;margin:0 0 14px}#panel-outreach .oc-tile{background:var(--card-bg,#16080a);border:1px solid var(--bdr);border-radius:12px;padding:12px}#panel-outreach .oc-tile .l{font-size:.66rem;text-transform:uppercase;letter-spacing:.06em;color:var(--txt3)}#panel-outreach .oc-tile .n{font-family:'Oswald',sans-serif;font-size:1.6rem;color:var(--txt)}#panel-outreach .oc-tile .s{font-size:.7rem;color:var(--txt2)}
      #panel-outreach .oc-card{background:var(--card-bg,#16080a);border:1px solid var(--bdr);border-radius:14px;padding:14px;margin-bottom:10px}#panel-outreach .oc-h{display:flex;gap:8px;align-items:center;flex-wrap:wrap}#panel-outreach .oc-h b{font-size:.98rem;color:var(--txt)}#panel-outreach .oc-tag{font-size:.64rem;border:1px solid var(--bdr2);border-radius:99px;padding:2px 9px;color:var(--txt2)}#panel-outreach .oc-due{font-size:.66rem;font-weight:700;color:#111;background:#f59e0b;border-radius:99px;padding:2px 9px}
      #panel-outreach .oc-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:10px;margin-top:10px}#panel-outreach .oc-f label{display:block;font-size:.66rem;color:var(--txt3);margin-bottom:3px}#panel-outreach .oc-links{display:flex;gap:6px;flex-wrap:wrap;margin-top:10px}#panel-outreach .oc-links a,#panel-outreach .oc-links button{font-size:.76rem;border:1px solid var(--bdr2);background:var(--dk2);color:var(--txt);border-radius:99px;padding:6px 12px;text-decoration:none;cursor:pointer}#panel-outreach .oc-links .pri{background:var(--gold);color:#111;border-color:var(--gold);font-weight:700}#panel-outreach .oc-route{font-size:.74rem;color:var(--txt3);margin-top:8px}#panel-outreach .oc-flt{display:flex;gap:6px;flex-wrap:wrap;margin:0 0 12px}#panel-outreach .oc-flt button{border:1px solid var(--bdr2);background:var(--dk2);color:var(--txt2);border-radius:99px;padding:6px 12px;font-size:.76rem;cursor:pointer}#panel-outreach .oc-flt button.on{background:var(--gold);color:#111;border-color:var(--gold);font-weight:700}</style>
      <div class="page-title mb-2"><i class="bi bi-megaphone-fill me-2" style="color:var(--gold)"></i>Outreach: universities &amp; colleges</div>
      <p class="muted" style="margin:-4px 0 12px;font-size:.8rem;color:var(--txt3)">Open each email, send it from the Email tab, then track the reply here. Bookings from the student pages are counted automatically. <span id="ocSaved" style="margin-left:6px">${S.hasDb ? "" : "Saved in this browser only"}</span></p>
      <div class="oc-tiles">${tile("Targets", ITEMS.length, "13 emails ready")}${tile("Contacted", sent, cnt("replied") + " replied")}${tile("Follow-ups due", due, "emailed 7+ days ago")}${tile("Agreed", cnt("agreed"), cnt("talks") + " in talks")}${tile("Bookings from pages", bk, fl + " from flyers")}</div>
      <div class="oc-flt">${[["all", "All"], ["University", "Universities"], ["College", "Colleges"], ["due", "Follow-up due"], ["none", "Not contacted"], ["emailed", "Emailed"], ["replied", "Replied"], ["agreed", "Agreed"]].map(f => `<button data-f="${f[0]}" class="${S.filter === f[0] ? "on" : ""}">${f[1]}</button>`).join("")}</div>
      ${shown.map(r => { const i = r.i, d = r.d, dd = days(d.emailed), isDue = d.status === "emailed" && dd != null && dd >= 7; return `<div class="oc-card" data-id="${i.id}">
        <div class="oc-h"><b>${h(i.name)}</b><span class="oc-tag">${i.kind}</span>${isDue ? `<span class="oc-due">Follow up · ${dd} days</span>` : ""}<span style="margin-left:auto;font-size:.76rem;color:var(--txt2)">${r.c.n ? `<b style="color:#4ade80">${r.c.n}</b> booking${r.c.n === 1 ? "" : "s"}${r.c.flyer ? ` (${r.c.flyer} flyer)` : ""}` : "No bookings yet"}</span></div>
        <div class="oc-grid">
          <div class="oc-f"><label>Status</label><select class="dsq-inp" data-k="status">${STATUS.map(s => `<option value="${s[0]}"${d.status === s[0] ? " selected" : ""}>${s[1]}</option>`).join("")}</select></div>
          <div class="oc-f"><label>Date emailed</label><input class="dsq-inp" type="date" data-k="emailed" value="${h(d.emailed)}"></div>
          <div class="oc-f"><label>Contact (name or email)</label><input class="dsq-inp" type="text" data-k="contact" value="${h(d.contact)}" placeholder="Who you wrote to"></div>
          <div class="oc-f"><label>Notes</label><input class="dsq-inp" type="text" data-k="notes" value="${h(d.notes)}" placeholder="Reply, next step…"></div></div>
        <div class="oc-links"><button class="pri" data-open="${h(i.tpl)}"><i class="bi bi-envelope-paper me-1"></i>Open the email</button><button data-mark="1"><i class="bi bi-check2 me-1"></i>Mark emailed today</button><a href="${h(i.flyer)}" target="_blank" rel="noopener"><i class="bi bi-file-earmark-pdf me-1"></i>Flyer PDF</a><a href="${h(i.page)}" target="_blank" rel="noopener"><i class="bi bi-box-arrow-up-right me-1"></i>Student page</a>${i.routeUrl ? `<a href="${h(i.routeUrl)}" target="_blank" rel="noopener"><i class="bi bi-person-lines-fill me-1"></i>Where to send</a>` : ""}<label style="display:inline-flex;gap:6px;align-items:center;font-size:.76rem;color:var(--txt2)"><input type="checkbox" data-k="flyer"${d.flyer ? " checked" : ""}> Flyer sent</label></div>
        <div class="oc-route"><i class="bi bi-signpost-split me-1"></i>${h(i.route)}</div></div>`; }).join("") || '<div class="muted">Nothing in this view.</div>'}`;
    $$(".oc-flt button", p).forEach(b => b.addEventListener("click", () => { S.filter = b.dataset.f; render(); }));
    $$(".oc-card", p).forEach(card => {
      const id = card.dataset.id, d = get(id);
      $$("[data-k]", card).forEach(el => el.addEventListener("change", () => { d[el.dataset.k] = el.type === "checkbox" ? el.checked : el.value; if (el.dataset.k === "status" && el.value === "emailed" && !d.emailed) d.emailed = today(); save(); render(); }));
      $$("[data-k][type=text]", card).forEach(el => el.addEventListener("input", () => { d[el.dataset.k] = el.value; save(); }));
      $("[data-mark]", card).addEventListener("click", () => { d.status = d.status === "none" ? "emailed" : d.status; d.emailed = today(); save(); render(); toast("Marked as emailed today", "success", 1800); });
      $("[data-open]", card).addEventListener("click", e => openTemplate(e.currentTarget.dataset.open));
    });
  }
  async function openTemplate(tpl) {
    const wait = ms => new Promise(r => setTimeout(r, ms));
    try { window.switchTab("email"); } catch (e) {}
    for (let k = 0; k < 20; k++) { await wait(250); const tb = $$("#panel-email [data-tab]").find(x => /template/i.test(x.textContent)); if (tb) { tb.click(); break; } }
    for (let k = 0; k < 20; k++) { await wait(250); const u = $('[data-usetpl="' + tpl + '"]'); if (u) { u.click(); toast("Email loaded. Check it, send yourself a test, then send to the contact you added.", "success", 6000); return; } }
    toast("Open Email → Templates → Universities & colleges to find it.", "warn", 6000);
  }
  async function open() { const p = $("#panel-outreach"); if (p && !S.loaded) p.innerHTML = '<div class="muted" style="padding:30px;text-align:center">Loading outreach…</div>'; await load(); render(); }
  function mount() {
    if ($("#panel-outreach")) return;
    try { if (typeof TABS !== "undefined" && TABS.indexOf("outreach") < 0) TABS.push("outreach"); } catch (e) {}
    const anchor = $("#tab-enquiries") || $("#tab-find");
    if (anchor && !$("#tab-outreach")) {
      const b = document.createElement("button"); b.className = "dsq-tab"; b.id = "tab-outreach"; b.title = "Outreach to universities and colleges";
      b.setAttribute("onclick", "switchTab('outreach')"); b.innerHTML = '<i class="bi bi-megaphone-fill"></i><span class="d-none d-sm-inline ms-1">Outreach</span>';
      anchor.insertAdjacentElement("afterend", b);
    }
    const after = $("#panel-enquiries") || $("#panel-waitlist") || $("#panel-dashboard");
    if (after) { const p = document.createElement("div"); p.id = "panel-outreach"; p.className = "hidden"; after.insertAdjacentElement("afterend", p); }
    if (typeof window.switchTab === "function" && !window.switchTab.__dsqoc) {
      const sw = window.switchTab; const w = function (t) { const r = sw.apply(this, arguments); if (t === "outreach") open(); return r; };
      Object.keys(sw).forEach(k => { w[k] = sw[k]; }); w.__dsqoc = true; window.switchTab = w;
    }
  }
  function init() { mount(); if (!$("#tab-outreach")) setTimeout(mount, 1500); }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init); else init();
})();
</script>
<!-- DSQ-OUTREACH END -->
'''
js = JS.replace("__ITEMS__", json.dumps(items, ensure_ascii=False, indent=1))
p = os.path.join(ROOT, "admin.html"); s = open(p, encoding="utf-8").read()
if "DSQ-OUTREACH START" in s:
    s = re.sub(r"<!-- DSQ-OUTREACH START.*?<!-- DSQ-OUTREACH END -->\n", lambda m: js, s, flags=re.S)
else:
    a = "<!-- DSQ-AUTOMAIL END -->"; assert s.count(a) == 1; s = s.replace(a, a + "\n" + js, 1)
open(p, "w", encoding="utf-8").write(s); print("outreach targets:", len(items))
